<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';if(admin())redirect('/admin/dashboard.php');if(empty($_SESSION['pending_mfa_admin_id'])||time()>(int)($_SESSION['pending_mfa_expires']??0))redirect('/admin/login.php');$error=null;if(is_post()){verify_csrf();if(complete_mfa_login(trim((string)input('code'))))redirect('/admin/dashboard.php');$error='The verification code is invalid or expired.';}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify identity · Hunter Wallet</title><link rel="stylesheet" href="<?=e(app_url('/assets/css/style.css'))?>"></head><body class="login-page"><section class="login-card"><h1>Verification required</h1><p>Enter the six-digit code from your authenticator app.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post"><?=csrf_field()?><div class="field"><label for="code">Authenticator code</label><input id="code" name="code" inputmode="numeric" pattern="\d{6}" maxlength="6" autocomplete="one-time-code" required autofocus></div><button class="btn" type="submit">Verify and sign in</button><a class="btn secondary" href="<?=e(app_url('/admin/login.php'))?>">Start again</a></form></section></body></html>
